pub fn bucketByMnemonic(mnemonic: []const u8) ?InstructionBucket {
    for (instruction_names, 0..) |name, index| {
        if (std.ascii.eqlIgnoreCase(name, mnemonic)) return instruction_buckets[index];
    }
    return null;
}

pub fn templateAt(index: u32) ?Template {
    if (index >= templates.len) return null;
    return templates[@intCast(index)];
}

pub fn reserveUnitBytes(opcode: u16) u8 {
    if (opcode >= reserve_unit_bytes.len) return 0;
    return reserve_unit_bytes[opcode];
}

pub fn bytecodeForTemplate(template: Template) ?[]const u8 {
    const start: usize = @intCast(template.bytecode_offset);
    if (start >= bytecodes.len) return null;
    const len: usize = @intCast(template.bytecode_len);
    if (len == 0) return null;
    const end = start + len;
    if (end > bytecodes.len) return null;
    return bytecodes[start..end];
}
